-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

-- An ORC union with more branches than Variant can hold (255) is valid ORC but not representable.
-- It must be reported as an unsupported ORC type (and be skippable), not fail with a confusing
-- BAD_ARGUMENTS from the Variant constructor. The union below has 256 distinct branches
-- (char(1)..char(255) and int) - distinct, so the duplicate-branch rejection cannot mask the
-- branch-count guard.

SET allow_experimental_variant_type = 1;

-- Schema inference rejects the oversized union.
DESC format(ORC, unhex('')); -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }
SELECT * FROM format(ORC, unhex('')) FORMAT Null; -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }

-- The oversized-union column is skipped and the remaining supported columns are still read (here a
-- plain Int32 'id'), instead of failing the whole file.
SELECT * FROM format(ORC, unhex('')) ORDER BY id SETTINGS input_format_orc_skip_columns_with_unsupported_types_in_schema_inference = 1 FORMAT TSVWithNames;

-- With an explicit structure the data-read path also rejects the oversized union cleanly.
SELECT * FROM format(ORC, 'u String', unhex('')) FORMAT Null; -- { serverError UNKNOWN_TYPE }
